<?php
declare(strict_types=1);
$role=current_role();if(!in_array($role,['aluno','professor'],true)){go('dashboard');}
$id=current_link_id();
$person=null;$classes=[];$grades=[];$enrollments=[];$benefit=null;$phones=[];
if($role==='professor'){
 $person=one('SELECT * FROM professor WHERE id_professor=?',[$id]);
 $classes=query('SELECT x.id_execucao,x.ano,x.semestre,d.nome disciplina,c.nome curso,COUNT(m.id_matricula) matriculados,ROUND(AVG(m.media),2) media FROM execucao_disciplina x JOIN disciplina d ON d.id_disciplina=x.id_disciplina JOIN curso c ON c.id_curso=x.id_curso LEFT JOIN matricula_disciplina m ON m.id_execucao=x.id_execucao WHERE x.id_professor=? GROUP BY x.id_execucao,x.ano,x.semestre,d.nome,c.nome ORDER BY x.ano DESC,x.semestre DESC,d.nome',[$id]);
 $turma=(int)($_GET['turma']??0);$selected=($turma>0)?one('SELECT x.id_execucao,d.nome disciplina,c.nome curso,x.ano,x.semestre FROM execucao_disciplina x JOIN disciplina d ON d.id_disciplina=x.id_disciplina JOIN curso c ON c.id_curso=x.id_curso WHERE x.id_execucao=? AND x.id_professor=?',[$turma,$id]):null;
 if($selected)$grades=query('SELECT m.id_matricula,a.nome,a.matricula,m.nota1,m.nota2,m.media FROM matricula_disciplina m JOIN aluno a ON a.id_aluno=m.id_aluno WHERE m.id_execucao=? ORDER BY a.nome',[$turma]);
 $areas=query('SELECT area_atuacao FROM area_professor WHERE id_professor=? ORDER BY area_atuacao',[$id]);
}else{
 $person=one('SELECT * FROM aluno WHERE id_aluno=?',[$id]);
 $enrollments=query('SELECT c.nome curso,i.numero_inscricao,i.ano_inicio,i.ano_conclusao,i.ativa FROM inscricao i JOIN curso c ON c.id_curso=i.id_curso WHERE i.id_aluno=? ORDER BY i.numero_inscricao DESC',[$id]);
 $grades=query('SELECT d.nome disciplina,c.nome curso,p.nome professor,x.ano,x.semestre,m.nota1,m.nota2,m.media FROM matricula_disciplina m JOIN execucao_disciplina x ON x.id_execucao=m.id_execucao JOIN disciplina d ON d.id_disciplina=x.id_disciplina JOIN curso c ON c.id_curso=x.id_curso JOIN professor p ON p.id_professor=x.id_professor WHERE m.id_aluno=? ORDER BY x.ano DESC,x.semestre DESC,d.nome',[$id]);
 $benefit=one('SELECT nome_programa,valor_beneficio FROM auxilio_estudantil WHERE id_aluno=?',[$id]);
 $phones=query('SELECT telefone FROM telefone_aluno WHERE id_aluno=?',[$id]);
}
if(!$person){http_response_code(403);exit('Conta sem cadastro acadêmico válido. Peça ao administrador para revisar o vínculo.');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $role==='professor'?'Portal do Professor':'Portal do Aluno'?> | Faculdade</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="portal-shell"><header class="portal-header"><a href="<?=e(url('portal'))?>" class="brand">🎓 FACULDADE <small>PORTAL <?= $role==='professor'?'DOCENTE':'DO ALUNO'?></small></a><span><?=e($person['nome'])?></span><form action="<?=e(url('logout'))?>" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><button class="btn muted">Sair</button></form></header><main class="portal-content"><section class="portal-hero"><p class="eyebrow"><?= $role==='professor'?'PAINEL DOCENTE':'ÁREA DO ESTUDANTE'?></p><h1>Olá, <?=e($person['nome'])?>!</h1><p><?= $role==='professor'?'Gerencie suas turmas e lance as avaliações dos seus estudantes.':'Consulte sua vida acadêmica, suas avaliações e seu auxílio estudantil.'?></p></section><?php if(!empty($_SESSION['flash'])):?><div class="alert <?=e($_SESSION['flash']['type'])?>"><?=e($_SESSION['flash']['message'])?></div><?php unset($_SESSION['flash']);endif;?>
<?php if($role==='professor'): ?>
<div class="portal-stats"><article class="metric"><small>Turmas atribuídas</small><strong><?=count($classes)?></strong></article><article class="metric"><small>Total de matrículas nas turmas</small><strong><?=array_sum(array_map(fn($x)=>(int)$x['matriculados'],$classes))?></strong></article><article class="metric"><small>Titulação</small><strong><?=e($person['titulacao'])?></strong></article></div>
<section class="panel"><h2>Minhas turmas</h2><p>Clique em uma turma para consultar a lista de alunos e lançar notas.</p><div class="table-scroll"><table><thead><tr><th>Disciplina</th><th>Curso</th><th>Período</th><th>Alunos</th><th>Média da turma</th><th></th></tr></thead><tbody><?php foreach($classes as $c):?><tr><td><?=e($c['disciplina'])?></td><td><?=e($c['curso'])?></td><td><?=e($c['ano'].'/'.$c['semestre'])?></td><td><?=e($c['matriculados'])?></td><td><?=e($c['media']??'—')?></td><td><a class="btn muted" href="<?=e(url('portal',['turma'=>$c['id_execucao']]))?>#notas">Lançar notas</a></td></tr><?php endforeach;if(!$classes):?><tr><td colspan="6" class="empty">Ainda não há turmas atribuídas a você.</td></tr><?php endif;?></tbody></table></div></section>
<?php if($selected):?><section class="panel" id="notas"><h2>Notas — <?=e($selected['disciplina'])?></h2><p><?=e($selected['curso'].' · '.$selected['ano'].'/'.$selected['semestre'])?>. Informe notas entre 0 e 10; a média é automática.</p><div class="table-scroll"><table><thead><tr><th>Aluno</th><th>Matrícula</th><th>Nota 1</th><th>Nota 2</th><th>Média</th><th>Salvar</th></tr></thead><tbody><?php foreach($grades as $g):?><tr><td><?=e($g['nome'])?></td><td><?=e($g['matricula'])?></td><td><input class="grade-input" type="number" name="nota1" form="grade-<?=e($g['id_matricula'])?>" min="0" max="10" step="0.01" value="<?=e($g['nota1'])?>"></td><td><input class="grade-input" type="number" name="nota2" form="grade-<?=e($g['id_matricula'])?>" min="0" max="10" step="0.01" value="<?=e($g['nota2'])?>"></td><td><strong><?=e($g['media']??'Pendente')?></strong></td><td><form id="grade-<?=e($g['id_matricula'])?>" method="post" action="<?=e(url('grades_save'))?>"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="matricula" value="<?=e($g['id_matricula'])?>"><input type="hidden" name="turma" value="<?=e($selected['id_execucao'])?>"><button class="btn primary">Salvar</button></form></td></tr><?php endforeach;if(!$grades):?><tr><td colspan="6" class="empty">Nenhum aluno matriculado nesta oferta.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
<section class="panel"><h2>Minhas áreas de atuação</h2><p><?=e(implode(' · ',array_column($areas,'area_atuacao'))?:'Nenhuma área cadastrada')?></p></section>
<?php else:?>
<div class="portal-stats"><article class="metric"><small>Matrícula</small><strong><?=e($person['matricula'])?></strong></article><article class="metric"><small>Situação</small><strong><?=e($person['status_aluno'])?></strong></article><article class="metric"><small>Disciplinas cursadas</small><strong><?=count($grades)?></strong></article></div><section class="panel"><h2>Meus cursos</h2><div class="table-scroll"><table><thead><tr><th>Inscrição</th><th>Curso</th><th>Início</th><th>Conclusão</th><th>Situação</th></tr></thead><tbody><?php foreach($enrollments as $i):?><tr><td>#<?=e($i['numero_inscricao'])?></td><td><?=e($i['curso'])?></td><td><?=e($i['ano_inicio'])?></td><td><?=e($i['ano_conclusao']??'—')?></td><td><?= $i['ativa']?'Ativa':'Inativa'?></td></tr><?php endforeach;if(!$enrollments):?><tr><td colspan="5" class="empty">Nenhuma inscrição localizada.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h2>Meu boletim</h2><button class="btn muted" onclick="window.print()">Imprimir</button></div><div class="table-scroll"><table><thead><tr><th>Disciplina</th><th>Curso</th><th>Professor</th><th>Período</th><th>Nota 1</th><th>Nota 2</th><th>Média</th></tr></thead><tbody><?php foreach($grades as $g):?><tr><td><?=e($g['disciplina'])?></td><td><?=e($g['curso'])?></td><td><?=e($g['professor'])?></td><td><?=e($g['ano'].'/'.$g['semestre'])?></td><td><?=e($g['nota1']??'—')?></td><td><?=e($g['nota2']??'—')?></td><td><strong><?=e($g['media']??'Pendente')?></strong></td></tr><?php endforeach;if(!$grades):?><tr><td colspan="7" class="empty">Sem disciplinas matriculadas.</td></tr><?php endif;?></tbody></table></div></section><div class="portal-two"><section class="panel"><h2>Meus dados</h2><p><b>Nome:</b> <?=e($person['nome'])?></p><p><b>Nascimento:</b> <?=e($person['data_nascimento']??'—')?></p><p><b>Telefones:</b> <?=e(implode(', ',array_column($phones,'telefone'))?:'—')?></p></section><section class="panel"><h2>Auxílio estudantil</h2><?php if($benefit):?><p><?=e($benefit['nome_programa'])?></p><h2><?=money($benefit['valor_beneficio'])?></h2><?php else:?><p>Você não possui auxílio cadastrado.</p><?php endif;?></section></div>
<?php endif;?></main><footer class="portal-footer">FACULDADE · Sistema Acadêmico PHP + MySQL</footer></div></body></html>
